//! Cargo-driven `pcix.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is pcix-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DriverEntry@8", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "DriverEntry", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DriverEntry", 0x7ffb00000000u64),
        o => panic!("pcix-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "import:ntoskrnl", "import:hal", "engine:arbiter_rust", "engine:c:memcmp"],
        "x86_64" => &["body", "import:ntoskrnl", "import:hal", "engine:arbiter_rust", "engine:c:memcmp"],
        "aarch64" => &["body", "import:ntoskrnl", "import:hal", "engine:arbiter_rust", "engine:c:memcmp"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/drivers/bus/pcix",
        "drivers/bus/pcix",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/reactos/drivers",
        "sdk/lib/drivers/arbiter",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502"];

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=-sse,-sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("pcix-rust")
        .rust_user_target()
        .c_from_compile_db("pcix_shims", &["drivers/bus/pcix/rust_varargs_shim.c", "drivers/bus/pcix/usage.c", "drivers/bus/pcix/intrface/ideintrf.c", "drivers/bus/pcix/pci/devhere.c", "drivers/bus/pcix/pci/romimage.c", "drivers/bus/pcix/guid.c"])
        .rc("drivers/bus/pcix/pci.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
